import React, { useState } from "react";
import { useTranslation } from "react-i18next";
import axios from "axios";
import { toast, ToastContainer } from "react-toastify";
// import "react-toastify/dist/ReactToastify.css";

import pic from "../../assets/contact.png";
import style from "./Contact.module.css";

const Contact = () => {
  const { t } = useTranslation();
  const [name, setName] = useState("");
  const [email, setEmail] = useState("");
  const [message, setMessage] = useState("");

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    const dataToSend = {
      name,
      email,
      message,
    };

    try {
      await axios.post(
        "https://portfolio-api-two-rosy.vercel.app/api/contact",
        dataToSend,
      );

      // Alert o'rniga muvaffaqiyatli notification
      toast.success("Iltimos! Emailingizni tekshiring!");

      setName("");
      setEmail("");
      setMessage("");
    } catch (error) {
      console.error(error);

      // Xatolik yuz berganda chiqadigan notification
      toast.error("Xatolik yuz berdi. Qaytadan urinib ko'ring!");
    }
  };

  return (
    <div className={style.Contact}>
      {/* Toast popup xabarlari ko'rinishi uchun bildirishnoma konteyneri */}
      <ToastContainer position="top-right" autoClose={3000} />

      <div className={style.ContactContent}>
        <h1>
          {t("contactTitle")} <br /> <span> {t("contactTitle2")} </span>
        </h1>
        <img src={pic} alt="" />
      </div>
      <form onSubmit={handleSubmit} className={style.ContactForm}>
        <input
          type="text"
          id="name"
          data-testid="contact-name-input"
          required
          placeholder={t("contactNamePlaceholder")}
          value={name}
          onChange={(e) => setName(e.target.value)}
        />
        <input
          type="email"
          id="email"
          data-testid="contact-email-input"
          // required
          placeholder={t("contactEmailPlaceholder")}
          value={email}
          onChange={(e) => setEmail(e.target.value)}
        />
        <textarea
          id="message"
          data-testid="contact-message-input"
          required
          placeholder={t("contactMessagePlaceholder")}
          value={message}
          onChange={(e) => setMessage(e.target.value)}
        ></textarea>
        <button data-testid="contact-submit-btn" type="submit">
          {t("contactBtn")}
        </button>
      </form>
    </div>
  );
};

export default Contact;
